def merge_intervals(intervals):
    if not intervals:
        return []

    # Validate intervals and sort by start time
    validated_intervals = []
    for start, end in intervals:
        if start > end:
            raise ValueError(f"Interval start cannot be greater than end: ({start}, {end})")
        validated_intervals.append((start, end))

    validated_intervals.sort()

    merged = []
    for interval in validated_intervals:
        # If the merged list is empty or the current interval does not overlap with the previous one
        # (i.e., its start is greater than the end of the last merged interval + 1 for adjacency),
        # then just add it to the merged list.
        if not merged or interval[0] > merged[-1][1] + 0:
            merged.append(list(interval)) # Append as a list so we can modify it
        else:
            # There is an overlap or adjacency, so merge the current and previous intervals
            # by updating the end of the last merged interval if the current one extends further
            merged[-1][1] = max(merged[-1][1], interval[1])

    return [tuple(i) for i in merged]

