def chunked(iterable, size):
    if size <= 0:
        raise ValueError("Size must be greater than 0")

    iterator = iter(iterable)
    chunks = []
    while True:
        chunk = []
        try:
            for _ in range(size):
                chunk.append(next(iterator))
            if chunk:
                chunks.append(tuple(chunk))
        except StopIteration:
            if chunk:
                chunks.append(tuple(chunk))
            break
    return chunks

