import re

def parse_duration(value):
    if not value or not value.strip():
        raise ValueError("Input string cannot be empty.")

    total_seconds = 0
    terms = value.strip().split()
    found_valid_term = False

    for term in terms:
        match = re.fullmatch(r'(\d+)([hms])', term, re.IGNORECASE)
        if not match:
            raise ValueError(f"Invalid duration term: '{term}'. Expected format like '1h', '30m', '5s'.")

        quantity_str, unit = match.groups()
        try:
            quantity = int(quantity_str)
        except ValueError:
            raise ValueError(f"Invalid quantity '{quantity_str}' in term '{term}'. Quantity must be an integer.")

        if unit.lower() == 'h':
            total_seconds += quantity * 3600
            found_valid_term = True
        elif unit.lower() == 'm':
            total_seconds += quantity * 60
            found_valid_term = True
        elif unit.lower() == 's':
            total_seconds += quantity
            found_valid_term = True
        else:
            # This case should ideally be caught by the regex, but as a fallback
            raise ValueError(f"Unknown unit '{unit}' in term '{term}'. Only 'h', 'm', 's' are allowed.")

    if not found_valid_term and not terms:
        raise ValueError("Input string has no valid duration terms.")

    return total_seconds

