    for start, end in intervals:
        if start > end:
            raise ValueError(f"Invalid interval: ({start}, {end}). Start cannot be greater than end.")

    intervals.sort()

    merged = []
    for current_start, current_end in intervals:
        if not merged or current_start > merged[-1][1]:
            # No overlap or touch, add as new interval
            merged.append([current_start, current_end])
        else:
            # Overlap or touch, merge with the last interval
            merged[-1][1] = max(merged[-1][1], current_end)

    return [tuple(i) for i in merged]

