import itertools

def chunked(iterable, size):
    if size <= 0:
        raise ValueError("Chunk size must be greater than 0.")

    it = iter(iterable)
    while True:
        chunk = tuple(itertools.islice(it, size))
        if not chunk:
            break
        yield chunk

def chunked_wrapper(iterable, size):
    return list(chunked(iterable, size))

