        # Check for invalid terms if no valid terms were found but the string isn't empty
        if not all(re.match(r'^(\d+[hms]?\s*)+$', value.strip(), re.IGNORECASE).groups()):
            raise ValueError("String contains no valid duration terms or has invalid characters")


    return total_seconds

